import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { router } from 'kea-router'
import type { LocationChangedPayload } from 'kea-router/lib/types'

import { removeProjectIdIfPresent } from 'lib/utils/kea-router'
import { toolHrefForPath } from 'scenes/tools/toolsUtils'

export const TODAY_RECENTS_LIMIT = 5

function pushRecent(list: string[], value: string): string[] {
    return [value, ...list.filter((item) => item !== value)].slice(0, TODAY_RECENTS_LIMIT)
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRecentsLogicValues {
    recentToolHrefs: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRecentsLogicActions {
    recordLocation: (pathname: string) => {
        pathname: string
    }
    recordToolVisit: (href: string) => {
        href: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayRecentsLogicMeta {
    __keaTypeGenInternalReducerActions: {
        'location changed (kea.router)': ({
            method,
            pathname,
            search,
            searchParams,
            hash,
            hashParams,
            initial,
            url,
            routerState,
        }: LocationChangedPayload) => {
            payload: {
                hash: string
                hashParams: Record<string, any>
                initial: boolean
                method: 'POP' | 'PUSH' | 'REPLACE'
                pathname: string
                routerState: Record<string, any>
                search: string
                searchParams: Record<string, any>
                url: string
            }
            type: 'location changed (kea.router)'
        }
    }
}

export type todayRecentsLogicType = MakeLogicType<
    todayRecentsLogicValues,
    todayRecentsLogicActions,
    Record<string, any>,
    todayRecentsLogicMeta
>

/**
 * What the Tools pane lists as recently viewed.
 * Tools have no server record of views, so this browser keeps one as the user moves between pages.
 */
export const todayRecentsLogic = kea<todayRecentsLogicType>([
    path(['layout', 'today', 'todayRecentsLogic']),
    actions({
        recordToolVisit: (href: string) => ({ href }),
        recordLocation: (pathname: string) => ({ pathname }),
    }),
    reducers({
        // pinned: storage keys for persisted state. Renaming them clears everyone's recents.
        recentToolHrefs: [
            [] as string[],
            { persist: true },
            { recordToolVisit: (state, { href }) => pushRecent(state, href) },
        ],
    }),
    listeners(({ actions }) => ({
        recordLocation: ({ pathname }) => {
            const path = removeProjectIdIfPresent(pathname)
            const toolHref = toolHrefForPath(path)
            if (toolHref) {
                actions.recordToolVisit(toolHref)
            }
        },
        [router.actionTypes.locationChanged]: ({ pathname }: LocationChangedPayload) => {
            actions.recordLocation(pathname)
        },
    })),
    afterMount(({ actions }) => {
        actions.recordLocation(router.values.location.pathname)
    }),
])
